```
const { AndroidConfig, withAndroidManifest } = require('@expo/config-plugins')

const withForceDefaultFcmChannel = (config) => {
    return withAndroidManifest(config, async (config) => {
        config.modResults = await setForceDefaultFcmChannel(config, config.modResults)
        return config
    })
}

async function setForceDefaultFcmChannel(config, androidManifest) {
    // Ensure that the manifest has an application node
    const mainApplication = AndroidConfig.Manifest.getMainApplication(androidManifest)

    AndroidConfig.Manifest.addMetaDataItemToMainApplication(
        mainApplication,
        'com.google.firebase.messaging.default_notification_channel_id', // android:name
        'default', // android:value
        'value'
    );

    AndroidConfig.Manifest.addMetaDataItemToMainApplication(
        mainApplication,
        'expo.modules.notifications.default_notification_icon',
        '@drawable/notification_icon',
        'resource'
    );

    AndroidConfig.Manifest.addMetaDataItemToMainApplication(
        mainApplication,
        'expo.modules.notifications.default_notification_color',
        '@color/notification_icon_color',
        'resource'
    );

    return androidManifest
}

module.exports = withForceDefaultFcmChannel

```
